        raise CaseError(
            "'expected_value' 必须为解析后有限的数字"
            "（不接受 NaN、Infinity 或 1e400 这类溢出数值）"
        )
else:
    raise CaseError(
        "'expected_value' 必须为字符串、布尔值（true/false）、null"
        " 或有限数字"
    )

